# coding: utf-8
import json
from pathlib import Path
from lesson_authoring import entry as E
B=[['拉丁 vitium','缺陷、过错；身体或品行上的问题']]
W=[
E('vice','/vaɪs/','恶习、缺点；台钳〔英式，另源〕','这一族的 vice 是品行里的毛病：大可以是恶行，小可以是戒不掉的坏习惯。','恶习义经古法语 vice 来自拉丁 vitium。英式台钳义另接法语 vis“螺丝”和拉丁 vitis“藤”；职位里表“副”的 vice- 又来自拉丁 vicis“替代、轮换”一支。',B+[['古法语 vice → 英语 vice','缺点、罪恶 → 恶习；坏习惯']],'a vice 可以是严肃的道德缺点，也可以自嘲地说“我的小毛病”，如总忍不住吃甜食。vice 在英式英语还指台钳，美式多写 vise。读到 vice president 的副职含义，更不能硬解释为“坏总统”，三个来源必须分开。','a bad vice；virtues and vices；one’s only vice；英式 a bench vice。','vice 是恶习或缺陷，virtue 是美德；vice- 表副职与恶习无关。台钳义则是另一条螺旋、夹紧工具的词源。',('He joked that buying too many notebooks was his only vice.','他开玩笑说，买太多笔记本是自己唯一的坏毛病。'),('The carpenter held the wood firmly in a vice.','木匠用台钳把木头牢牢夹住。'),sources=['https://www.etymonline.com/word/vice','https://en.wiktionary.org/wiki/vice']),
E('vicious','/ˈvɪʃəs/','凶狠的、恶毒的；严重有害的','不是普通地不好，而是带着伤害力、攻击性或不断变坏的劲头。','经法语 vicious／vicios 或拉丁语借入，来自 vitiosus“有缺陷、邪恶的”，接 vitium；不能仅当成现代英语 vice 现场加 -ous。',B+[['拉丁 vitiosus → 法语 vicios／vicious','有缺陷的、邪恶的'],['英语 vicious','凶狠、恶毒；严重有害的']],'a vicious attack 可以是暴力袭击，也可以是恶毒抨击。a vicious circle 是恶性循环：一个坏结果又促成原来的坏原因，让状况越滚越差。这是缺陷、伤害一支的延伸，不是说圆圈本身会咬人。','a vicious attack；vicious criticism；a vicious circle；vicious rumours。','violent 主要强调暴力或猛烈，vicious 更容易强调凶狠、恶意或破坏性；恶毒言语未必涉及身体暴力。',('She faced a vicious personal attack during the debate.','辩论中，她遭到了恶毒的人身攻击。'),('Poor sleep and stress can form a vicious circle.','睡不好与压力可能形成恶性循环。'),sources=['https://www.etymonline.com/word/vicious','https://en.wiktionary.org/wiki/vicious']),
E('viciously','/ˈvɪʃəsli/','凶狠地、恶毒地；猛烈地','动作或话语带着明显的伤害劲头。','vicious + -ly，形容词变副词；英语早期已有相应形式，意义随 vicious 扩展。',B+[['英语 vicious → viciously','凶狠恶毒的 → 以凶狠恶毒的方式']],'attack someone viciously 可以是凶狠袭击，也可以是言语恶意攻击；criticise viciously 通常不只是批评很严，而是方式带有攻击性。这个副词放到句子里，会显著加强说话者对行为的负面判断。','attack viciously；criticise viciously；lash out viciously。','harshly 是严厉地，viciously 往往更含凶狠或恶意。不能把所有严格批评都形容为 viciously。',('The review attacked her character viciously instead of discussing the book.','那篇评论没有讨论书的内容，而是恶毒地攻击她的人格。'),('The dog snapped viciously at the intruder.','那条狗凶狠地朝闯入者咬去。'),sources=['https://en.wiktionary.org/wiki/viciously','https://www.etymonline.com/word/vicious']),
E('viciousness','/ˈvɪʃəsnəs/','凶狠、恶毒；伤害程度','把一次攻击或一种态度里狠毒的部分单独拿出来看。','vicious + -ness，表示性质或程度的名词；-ness 不改变前面的基本重音。',B+[['英语 vicious → viciousness','凶狠恶毒 → 这种性质或程度']],'the viciousness of the comments 是评论的恶毒程度；the viciousness of an attack 可以说袭击很凶狠。它描述表现出的性质，不是给一个人永久贴上某种医学或人格诊断。','the viciousness of；shocked by the viciousness；unexpected viciousness。','vicious 是形容词，viciousness 是名词；vice 是恶习或缺点，并不等于每一处 viciousness 的“凶狠程度”。',('She was shocked by the viciousness of the online comments.','网络评论的恶毒程度让她震惊。'),('The argument escalated with unexpected viciousness.','争吵以出乎意料的恶毒程度升级了。'),sources=['https://en.wiktionary.org/wiki/viciousness']),
E('vitiate','/ˈvɪʃieɪt/','损害质量；破坏效力〔正式〕','一个关键毛病渗进去，让原本该成立的东西站不稳了。','来自拉丁 vitiare“弄坏、使有缺陷”的分词 vitiatus，接 vitium；不是 vital“生命的”一族。',B+[['拉丁 vitiare → vitiatus','使有缺陷、破坏质量'],['英语 vitiate','损害质量、削弱或破坏效力']],'如果研究用了错误的数据，缺陷可能 vitiate the conclusions，让结论的可靠性受损。它常见于正式论述，强调缺陷破坏了本来的质量或效力；日常说 spoil、undermine 往往更自然。','vitiate an argument；vitiate the results；vitiate a conclusion。','invalidate 强调使不再有效，vitiate 可强调缺陷造成的质量或效力损害，严重程度要看语境。与 invigorate“使有活力”方向不同。',('The sampling error vitiated the conclusions of the study.','抽样错误损害了这项研究结论的可靠性。'),('A false assumption can vitiate an otherwise careful argument.','一个错误假设可能毁掉一套原本周密的论证。'),sources=['https://www.etymonline.com/word/vitiate','https://en.wiktionary.org/wiki/vitiate'])]
ROOT=dict(id='C1651',meaning='缺陷、过错；伤害和破坏',core='VITI = FAULT / DEFECT',image='一件东西里有了毛病，质量会坏；一个行为带着恶意，就会伤人。从缺陷到恶习、凶狠和破坏效力，是这一族的几条路。',intro='拉丁 vitium 可以说缺陷，也可以说道德上的过错。vice 常指恶习，vicious 发展出凶狠、恶毒，vitiate 则是让东西有缺陷、损害效力。原表误放进来的 viticulture 是葡萄栽培，来自 vitis“葡萄藤”，不属于这条缺陷词根。',forms='vitium 经法语变化成为 vice；vitiosus 一支成为 vicious；vitiare 的分词一支成为 vitiate。vice 的台钳义和副职前缀 vice- 各有其他来源，不能按拼写合并。',branches=[['品行里的毛病','vice'],['凶狠与恶毒','vicious, viciously, viciousness'],['让质量或效力受损','vitiate']],contrasts='vicious circle 是恶性循环，vice president 的 vice- 是副职，bench vice 是台钳。看见相同字母必须结合义项判断来源，不能用“邪恶”包办所有 vice。',practice='A false claim can vitiate an argument; a vicious attack can destroy a civil discussion.\n\n一个错误主张可能损害论证的可靠性；一次恶毒攻击可能毁掉理性的讨论。',words=[w['word'] for w in W],exclude={'viticulture':'误归类：来自拉丁 vitis“葡萄藤”，不是 vitium“缺陷”','vituperate':'较冷门的正式动词，按优先级暂略'})
if __name__=='__main__':
 for name,data in [('roots_viti',[ROOT]),('words_viti',W)]:Path('.cache/batch200/drafts/root/'+name+'.json').write_text(json.dumps(data,ensure_ascii=False,indent=2))
 print(len(W),sum(len(w['examples']) for w in W))
